window.CALCULATORS=window.CALCULATORS||[];window.CALCULATORS.push(  {id:"home-loan-emi",slug:"home-loan-emi-calculator",title:"Home Loan EMI Calculator",category:"loan",short:"Calculate a home-loan EMI, total interest and total repayment.",desc:"Estimate the monthly payment and long-run cost of a home loan using a fixed interest rate and repayment term.",article:{formula:"EMI = [P × r × (1+r)^n] ÷ [(1+r)^n − 1].",exampleInputs:{},faqs:[{q:"Does this include property taxes and insurance?",a:"No. It models the loan itself; recurring housing costs should be considered separately."},{q:"Why is total interest high on a long loan?",a:"A longer term leaves the balance outstanding for more months, so interest accumulates for longer."},{q:"Can I use a variable-rate loan?",a:"The model assumes the entered rate stays constant; recalculate when the applicable rate changes."}]},fields:[{id:"principal",label:"Home loan amount",type:"number",default:5000000,min:0,max:100000,step:1},{id:"rate",label:"Annual interest rate",type:"number",default:8.5,min:0,max:30,step:1},{id:"years",label:"Loan term",type:"number",default:20,min:1,max:40,step:1}],compute(v){const P=Math.max(v.principal,0),n=Math.max(1,Math.round(v.years*12)),r=Math.max(v.rate,0)/1200,emi=P===0?0:r===0?P/n:P*r*(1+r)**n/((1+r)**n-1),total=emi*n;return[{label:'Monthly home-loan EMI',value:emi,format:'currency',emphasis:'neutral'},{label:'Total repayment',value:total,format:'currency'},{label:'Total interest',value:total-P,format:'currency',emphasis:'negative'}];}});
